const vector = $json.data?.[0]?.embedding;
if (!Array.isArray(vector) || vector.length === 0) {
  throw new Error('OpenRouter tidak mengembalikan embedding. Pastikan server aktif dan model embedding sudah dimuat.');
}
return [{ json: { dimension: vector.length } }];

const { createHmac, timingSafeEqual } = require('crypto');
const item = $input.first();
const body = item.json.body || {};
const headers = item.json.headers || {};
const appSecret = String($env.WHATSAPP_APP_SECRET || '');

if (appSecret) {
  const actual = String(headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'] || '');
  const rawBase64 = item.binary?.data?.data || '';
  const raw = Buffer.from(rawBase64, 'base64');
  const expected = 'sha256=' + createHmac('sha256', appSecret).update(raw).digest('hex');
  const a = Buffer.from(actual);
  const b = Buffer.from(expected);
  if (!actual || a.length !== b.length || !timingSafeEqual(a, b)) {
    return [{ json: { kind: 'invalid_signature' } }];
  }
}

const value = body.entry?.[0]?.changes?.[0]?.value || {};
const messages = Array.isArray(value.messages) ? value.messages : [];
if (!messages.length) return [{ json: { kind: 'ignore', reason: 'status_or_empty_event' } }];

const contacts = value.contacts || [];
const ownerPhone = String($env.OWNER_PHONE || '').replace(/\D/g, '');
const output = [];
for (const message of messages) {
  const phone = String(message.from || '').replace(/\D/g, '');
  let text = '';
  if (message.type === 'text') text = message.text?.body || '';
  else if (message.type === 'button') text = message.button?.text || '';
  else if (message.type === 'interactive') {
    text = message.interactive?.button_reply?.title || message.interactive?.list_reply?.title || '';
  } else {
    text = '[Pelanggan mengirim pesan tipe ' + String(message.type || 'tidak dikenal') + '. Perlu ditangani owner.]';
  }
  const contact = contacts.find((x) => String(x.wa_id || '').replace(/\D/g, '') === phone) || contacts[0] || {};
  output.push({ json: {
    kind: 'message',
    message_id: String(message.id || ('generated-' + Date.now())),
    phone,
    name: contact.profile?.name || (phone === ownerPhone ? String($env.OWNER_NAME || 'Owner') : 'Pelanggan'),
    text: String(text).trim(),
    timestamp: new Date(Number(message.timestamp || Math.floor(Date.now() / 1000)) * 1000).toISOString(),
    is_owner: phone !== '' && phone === ownerPhone,
    message_type: message.type || 'text'
  } });
}
return output;

const raw = $input.first().json;
const value = Array.isArray(raw) ? (raw[0] ?? {}) : raw;
return [{ json: value?.result && Object.keys(value).length === 1 ? value.result : value }];

const ctx = $('Hasil Customer').first().json;
const search = $input.first().json || {};
const points = search.result?.points || search.points || search.result || [];
const knowledge = (Array.isArray(points) ? points : []).map((p) => ({
  score: p.score,
  content_type: p.payload?.content_type || 'chat_qa',
  category: p.payload?.category || '',
  auto_reply: p.payload?.auto_reply !== false && p.payload?.content_type !== 'price_reference',
  valid_from: p.payload?.valid_from || '',
  question: p.payload?.question || '',
  answer: p.payload?.answer || '',
  text: p.payload?.text || '',
  source: p.payload?.source || '',
  asset_id: p.payload?.asset_id || '',
  asset_description: p.payload?.asset_description || '',
  asset_caption: p.payload?.asset_caption || '',
  asset_path: p.payload?.asset_path || '',
  original_file_name: p.payload?.original_file_name || '',
  mime_type: p.payload?.mime_type || '',
  asset_kind: p.payload?.asset_kind || '',
  produk: p.payload?.produk || '',
  tags: Array.isArray(p.payload?.tags) ? p.payload.tags.join(', ') : (p.payload?.tags || '')
}));

// Pencocokan permintaan aset (size chart / katalog / price list / contoh produk) dengan image_asset yang ditemukan
const normAset = (s) => String(s || '').toLowerCase()
  .replace(/t\s*-?\s*shirt|\btee\b/g, 'kaos').replace(/jacket/g, 'jaket').replace(/celemek/g, 'apron')
  .replace(/tote\s*bag|goodie\s*bag|\btas\b/g, 'tote').replace(/id\s*card/g, 'idcard')
  .replace(/size\s*-?\s*chart|tabel\s+ukuran|daftar\s+ukuran|chart\s+ukuran|panduan\s+ukuran|ukuran\s+badan/g, 'sizechart')
  .replace(/price\s*-?\s*list|daftar\s+harga|list\s+harga/g, 'pricelist')
  .replace(/pilihan\s+warna|color\s*chart|swatch|contoh\s+warna|warna\s+kain/g, 'katalog');
const PRODUK = ['jaket', 'kaos', 'hoodie', 'sweater', 'crewneck', 'boxy', 'oversize', 'polo', 'kemeja', 'seragam', 'batik', 'varsity', 'jersey', 'tote', 'spunbond', 'topi', 'lanyard', 'idcard', 'apron', 'label', 'drill'];
const PAKAIAN = ['jaket', 'kaos', 'hoodie', 'sweater', 'crewneck', 'boxy', 'oversize', 'polo', 'kemeja', 'varsity'];
const STRUKTUR = ['size_chart', 'katalog', 'price_list'];
const produkDari = (s) => PRODUK.filter((p) => s.includes(p));
// Kelas aset: size_chart / katalog / price_list, sisanya (contoh produk/desain/referensi) = foto
const jenisAset = (e) => {
  if (STRUKTUR.includes(e.asset_kind)) return e.asset_kind;
  if (e.asset_kind) return 'foto';
  const t = normAset([e.asset_description, e.asset_caption, e.text].join(' '));
  return t.includes('sizechart') ? 'size_chart' : t.includes('pricelist') ? 'price_list' : /katalog/.test(t) ? 'katalog' : 'foto';
};
// asset_detail = jenis asli (contoh_produk, referensi_detail, ...), asset_kind = kelas untuk pencocokan
knowledge.forEach((e) => { if (e.content_type === 'image_asset') { e.asset_detail = e.asset_detail || e.asset_kind || ''; e.asset_kind = jenisAset(e); } });
const teksPermintaan = normAset(((ctx.recent_messages || []).filter((m) => m.sender === 'customer').slice(-2).map((m) => m.text).join(' ')) + ' ' + ctx.message_text);
const pesanTerakhir = normAset(ctx.message_text);
const produkDiminta = produkDari(teksPermintaan);
const tanyaUkuran = /\bukuran\b|\bsize\b/.test(pesanTerakhir) && (PAKAIAN.some((p) => teksPermintaan.includes(p)) || /ada apa|apa aja|apa saja|tersedia|berapa aja/.test(pesanTerakhir));
const jenisDiminta = /sizechart/.test(pesanTerakhir) || tanyaUkuran ? 'size_chart'
  : /pricelist/.test(pesanTerakhir) ? 'price_list'
  : /katalog/.test(pesanTerakhir) ? 'katalog'
  : /contoh|foto|gambar|mock\s*up|referensi|portofolio/.test(pesanTerakhir) && produkDiminta.length ? 'foto' : '';
const kandidatAset = jenisDiminta ? knowledge
  .filter((e) => e.content_type === 'image_asset' && e.asset_id && e.asset_path && String(e.mime_type).startsWith('image/') && jenisAset(e) === jenisDiminta)
  .map((e) => {
    const produkAset = produkDari(normAset([e.produk, e.asset_description, e.asset_caption, e.tags, e.text].join(' ')));
    const cocok = produkDiminta.filter((p) => produkAset.includes(p)).length;
    return { entry: e, skor: cocok * 10 - produkAset.length + Number(e.score || 0) + (String(e.asset_detail).startsWith('contoh') ? 5 : 0), cocok };
  })
  .filter((k) => produkDiminta.length ? k.cocok > 0 : true)
  .sort((a, b) => b.skor - a.skor) : [];
// Tanpa produk yang disebut dan lebih dari satu kandidat -> ambigu, biarkan model bertanya
const asetCocok = kandidatAset.length && (produkDiminta.length || kandidatAset.length === 1) ? kandidatAset[0].entry : null;
const assetRequest = { kind: jenisDiminta, produk: produkDiminta, match: asetCocok, kandidat: kandidatAset.map((k) => k.entry.asset_id),
  kandidat_produk: [...new Set(kandidatAset.map((k) => String(k.entry.produk || '').split('/')[0].trim()).filter(Boolean))] };


const system = `Anda adalah admin WhatsApp toko. Selalu gunakan Bahasa Indonesia.

ATURAN KERAS:
1. AUTO_REPLY hanya jika jawaban benar-benar didukung knowledge relevan atau data order pelanggan.
2. Jangan mengarang harga, stok, kebijakan, status order, resi, tanggal, atau janji.
3. Jika knowledge tidak menjawab, meragukan, konflik, atau membutuhkan keputusan owner, pilih ESCALATE.
4. Saat ESCALATE jangan membuat balasan pelanggan. Ringkas kebutuhan dan tulis pertanyaan spesifik untuk owner.
5. Balasan AUTO_REPLY harus meniru profil gaya owner, singkat, natural, dan tidak menyebut AI/vector database.
6. Data order adalah sumber resmi untuk status pesanan pelanggan ini.
7. Jika pelanggan meminta contoh/referensi gambar dan ada image_asset yang sangat relevan, pilih asset_id persis dari knowledge_relevan.
8. Jangan memilih aset yang hanya mirip secara umum. Jika pelanggan meminta gambar tetapi tidak ada image_asset yang relevan, pilih ESCALATE.
9. asset_id harus string kosong jika tidak perlu mengirim gambar.
10. Jika knowledge_relevan menjawab inti pertanyaan, walaupun jawabannya umum (mis. "tergantung jenis produk"), pilih AUTO_REPLY dan sampaikan jawaban itu. Jangan menjanjikan konfirmasi owner pada AUTO_REPLY.
11. Jangan menulis placeholder, asset_id, atau teks seperti [gambar] di reply. Gambar dikirim terpisah oleh sistem.
12. Pilih asset_id hanya jika isi gambar sama dengan yang diminta (jenis produk yang sama). Gambar produk lain dianggap tidak relevan.
13. tiket_terbuka berarti pertanyaan sebelumnya sedang menunggu jawaban owner. Ini TIDAK menghalangi percakapan: nilai pesan_pelanggan terbaru secara mandiri. Jika knowledge_relevan atau data_order menjawabnya, pilih AUTO_REPLY. Pilih ESCALATE hanya jika pesan terbaru itu sendiri membutuhkan owner, dan tulis ringkasan/pertanyaan owner hanya untuk pesan terbaru.
14. Jika pesan terbaru hanya menagih, mengulang, atau menanggapi pertanyaan di tiket_terbuka (mis. "jadi harganya berapa?", "oke ditunggu ya"), dan pesan itu jelas merujuk ke pertanyaan tersebut, pilih AUTO_REPLY, isi followup_tiket_terbuka = true, dan balas singkat bahwa pertanyaan itu sedang dicek owner dan akan segera dikabari. Jangan menjawab isi pertanyaan itu sendiri. Selain kasus ini followup_tiket_terbuka = false.
15. Jika pesan terbaru hanya sapaan, basa-basi, atau tes (mis. "halo", "permisi", "selamat siang", "tes", "makasih"), pilih AUTO_REPLY, isi sapaan = true, dan balas sapaan singkat yang ramah lalu tanyakan apa yang bisa dibantu. Jangan menyebut tiket atau owner, dan jangan ESCALATE. Selain kasus ini sapaan = false.
16. PERMINTAAN ASET (size chart/tabel ukuran, katalog warna, price list, contoh foto/desain): image_asset yang jenis dan produknya cocok dengan permintaan ADALAH jawaban. Pilih AUTO_REPLY, isi asset_id persis, dan tulis reply pengantar singkat (mis. "Baik kak, berikut size chart jaket kami ya 🙏"). Jangan ESCALATE hanya karena tidak ada chat_qa; gambar itu sudah menjawab.
17. permintaan_aset.aset_cocok adalah hasil pencocokan sistem (jenis aset + produk). Jika terisi, pakai asset_id itu kecuali pesan jelas meminta hal lain.
18. Size chart, katalog warna, dan price list BUKAN foto/mockup produk. Untuk permintaan size chart jangan kirim foto/mockup produk (mis. desain jaket varsity), dan untuk permintaan contoh desain/foto jangan kirim size chart.
19. Untuk permintaan gambar, ESCALATE hanya jika tidak ada satu pun image_asset yang cocok jenis dan produknya. Jika pesan juga menanyakan hal lain yang tidak ada di knowledge (mis. harga), tetap ESCALATE.
20. HARGA: knowledge content_type "price_list" adalah daftar harga resmi dan boleh dikutip apa adanya. Knowledge dengan auto_reply=false (content_type "price_reference") adalah harga deal pesanan lain: JANGAN dikutip ke pelanggan. Pertanyaan harga yang tidak tercakup price_list: pilih ESCALATE dan cantumkan referensi harga itu di owner_question agar owner cepat menjawab.
21. Jangan menulis nominal rupiah apa pun di reply yang tidak tertulis di knowledge dengan auto_reply=true atau di data_order.
22. Bila ada beberapa knowledge yang mirip, utamakan yang valid_from-nya paling baru.
23. Output wajib mengikuti JSON schema.`;

const payload = {
  profil_gaya_owner: "Owner (Bu Debi / admin SaViOr) membalas singkat, hangat, dan santai. Sapaan sesuai waktu: \"pagi..\", \"siang kak..\", \"sore bu..\"; panggil \"kak\" untuk pelanggan muda/umum, \"bu\"/\"pak\" untuk pelanggan yang lebih tua. Sering membuka dengan \"baik..\" atau \"iya bisa kak..\" lalu langsung ke inti. Kalimat pendek, sering diakhiri titik dua (..), memakai singkatan chat (y, yg, bs, dl, brp, ny, sdh) tetapi tetap jelas. Emoji secukupnya: 🤗 🙏🏻. Harga ditulis berbentuk daftar per ukuran (\"uk S, M : 65rb\"). Bila belum pasti, owner berkata akan mengecek/menghitungkan dulu, bukan menebak. Selalu menanyakan detail yang dibutuhkan untuk produksi: model, jenis kain, warna, sablon/bordir, jumlah per ukuran, dan tanggal dibutuhkan. Tidak menyebut AI atau sistem.",
  nama_pelanggan: ctx.customer_name,
  pesan_pelanggan: ctx.message_text,
  riwayat_terbaru: ctx.recent_messages,
  tiket_terbuka: ctx.open_ticket_code ? { kode: ctx.open_ticket_code, pertanyaan_menunggu_owner: ctx.open_ticket_question || '' } : null,
  data_order: ctx.orders,
  knowledge_relevan: knowledge,
  permintaan_aset: assetRequest.kind ? { jenis: assetRequest.kind, produk: assetRequest.produk, aset_cocok: asetCocok ? asetCocok.asset_id : '', kandidat: assetRequest.kandidat } : null
};

return [{ json: {
  context: ctx,
  knowledge,
  assetRequest,
  requestBody: {
    model: $env.OPENROUTER_MODEL,
    temperature: 0.25,
    max_tokens: 2500,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: JSON.stringify(payload) }
    ],
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'keputusan_admin_whatsapp',
        strict: true,
        schema: {
          type: 'object',
          additionalProperties: false,
          properties: {
            action: { type: 'string', enum: ['AUTO_REPLY', 'ESCALATE'] },
            confidence: { type: 'number', minimum: 0, maximum: 1 },
            reply: { type: 'string' },
            needs_summary: { type: 'string' },
            owner_question: { type: 'string' },
            asset_id: { type: 'string' },
            followup_tiket_terbuka: { type: 'boolean' },
            sapaan: { type: 'boolean' }
          },
          required: ['action', 'confidence', 'reply', 'needs_summary', 'owner_question', 'asset_id', 'followup_tiket_terbuka', 'sapaan']
        }
      }
    }
  }
} }];

const ctx = $('Hasil Customer').first().json;
const prep = $('Siapkan Keputusan AI').first().json;
let content = $json.choices?.[0]?.message?.content || $json.choices?.[0]?.message?.reasoning_content || '';
if (typeof content !== 'string') content = JSON.stringify(content);
content = content.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
let parsed;
try { parsed = JSON.parse(content); } catch { parsed = {}; }
if ($json.choices?.[0]?.finish_reason === 'length') parsed = {};
const llmFailed = !content;

const hasKnowledge = Array.isArray(prep.knowledge) && prep.knowledge.length > 0;
const hasOrders = Array.isArray(ctx.orders) && ctx.orders.length > 0;
let action = parsed.action === 'AUTO_REPLY' ? 'AUTO_REPLY' : 'ESCALATE';
// Buang placeholder gambar/asset yang kadang ditulis model, mis. "[Lampirkan gambar ...]"
let reply = String(parsed.reply || '')
  .replace(/\[[^\]]*(gambar|foto|image|asset|lampir)[^\]]*\]/gi, '')
  .replace(/[ \t]+\n/g, '\n').replace(/\s{2,}/g, ' ').trim();
// Tanggapan atas tiket yang masih menunggu owner: balas singkat, jangan eskalasi ulang.
// Balasan tidak boleh memuat angka (harga/tanggal/jumlah) karena jawabannya belum ada dari owner.
const ticketFollowup = Boolean(ctx.open_ticket_code) && parsed.followup_tiket_terbuka === true && action === 'AUTO_REPLY';
if (ticketFollowup && (!reply || /\d/.test(reply))) {
  reply = 'Baik kak, pertanyaan sebelumnya masih kami cek dengan owner ya. Nanti segera kami kabari 🙏';
}
const isGreeting = parsed.sapaan === true && action === 'AUTO_REPLY';
if (isGreeting && (!reply || /\d|owner|tiket|dicek/i.test(reply))) reply = 'Halo kak 👋 Ada yang bisa kami bantu?';
if (action === 'AUTO_REPLY' && !ticketFollowup && !isGreeting && (!reply || (!hasKnowledge && !hasOrders))) action = 'ESCALATE';

// Gambar hanya dikirim bila pelanggan meminta contoh/gambar/size chart pada pesan terakhirnya
const assetRequest = prep.assetRequest || {};
const recentCustomerText = (ctx.recent_messages || []).filter((m) => m.sender === 'customer').slice(-2).map((m) => m.text).join(' ') || ctx.message_text;
const askedForImage = Boolean(assetRequest.kind) ||
  /gambar|foto|contoh|katalog|referensi|lihat|desain|model|pic|photo|size\s*-?\s*chart|tabel\s+ukuran|price\s*-?\s*list|daftar\s+harga|mockup/i.test(recentCustomerText);
const isImageEntry = (entry) => entry.content_type === 'image_asset' && entry.asset_id && entry.asset_path && String(entry.mime_type).startsWith('image/');
const requestedAssetId = String(parsed.asset_id || '').trim();
let selectedAsset = askedForImage ? (prep.knowledge.find((entry) => isImageEntry(entry) && entry.asset_id === requestedAssetId) || null) : null;
// Aset pilihan model yang jenisnya beda dengan permintaan (mis. mockup jaket untuk "size chart jaket") dibuang
const matched = assetRequest.match || null;
let wrongKind = false;
if (selectedAsset && matched && selectedAsset.asset_id !== matched.asset_id && selectedAsset.asset_kind !== matched.asset_kind) { selectedAsset = null; wrongKind = true; }
// Untuk permintaan contoh produk, aset pilihan model harus produk yang sama (mis. bukan seragam untuk "contoh topi")
if (selectedAsset && matched && assetRequest.kind === 'foto' && !(assetRequest.kandidat || []).includes(selectedAsset.asset_id)) { selectedAsset = null; wrongKind = true; }
// Gambar referensi (detail/ukuran/model) bukan jawaban untuk "minta contoh" bila ada contoh produk/desain yang cocok
if (selectedAsset && matched && assetRequest.kind === 'foto' && String(selectedAsset.asset_detail).startsWith('referensi') && String(matched.asset_detail).startsWith('contoh')) { selectedAsset = null; wrongKind = true; }
// Pesan yang juga menanyakan hal yang butuh owner (harga, stok, jadwal, pesanan) tidak dijawab otomatis oleh sistem
const asksOther = /harga|biaya|ongkir|diskon|\bstok\b|kapan|deadline|tanggal|resi|pesanan saya|order saya|nego/i.test(ctx.message_text);
let assetOverride = false;
if (!selectedAsset && matched && (action === 'AUTO_REPLY' || !asksOther)) {
  // Ada aset yang cocok tetapi model eskalasi/gagal/lupa asset_id/memilih aset yang salah: kirim aset itu
  selectedAsset = matched;
  if (action !== 'AUTO_REPLY' || !reply || isGreeting || wrongKind || requestedAssetId) {
    const produk = String(matched.produk || '').split('/')[0].trim();
    const label = matched.asset_kind === 'size_chart' ? 'size chart ' + produk + ' kami'
      : matched.asset_kind === 'price_list' ? 'price list ' + produk + ' kami'
      : matched.asset_kind === 'katalog' ? 'katalog warna ' + produk + ' kami' : 'contoh ' + produk + ' kami';
    reply = 'Baik kak, berikut ' + label.replace(/\s+/g, ' ').trim() + ' ya 🙏';
    assetOverride = true;
  }
  action = 'AUTO_REPLY';
} else if (!selectedAsset && !matched && action !== 'AUTO_REPLY' && !asksOther && (assetRequest.kandidat_produk || []).length > 1) {
  // Minta size chart/katalog tanpa menyebut produk: tanyakan produknya, jangan eskalasi
  const daftar = assetRequest.kandidat_produk;
  reply = 'Boleh tahu untuk produk apa kak? Kami punya ' + (assetRequest.kind === 'size_chart' ? 'size chart ' : assetRequest.kind === 'katalog' ? 'katalog ' : assetRequest.kind === 'price_list' ? 'price list ' : '') +
    daftar.slice(0, -1).join(', ') + ' dan ' + daftar[daftar.length - 1] + ' 🙏';
  action = 'AUTO_REPLY';
  assetOverride = true;
}

// PENJAGA_NOMINAL: nominal rupiah di balasan otomatis harus berasal dari knowledge yang boleh dijawab atau data order
const toRupiah = (raw) => {
  const s = String(raw).toLowerCase().replace(/\s+/g, '');
  const unit = /jt|juta/.test(s) ? 1e6 : /rb|ribu|k$/.test(s) ? 1e3 : 1;
  const num = s.replace(/[^\d.,]/g, '');
  const value = unit > 1 ? Number(num.replace(',', '.')) : Number(num.replace(/[.,]/g, ''));
  return Math.round(value * unit);
};
const nominalDari = (s) => (String(s || '').match(/\d{1,3}(?:[.,]\d{3})+|\d+(?:[.,]\d+)?\s*(?:rb|ribu|jt|juta|k)\b/gi) || []).map(toRupiah).filter((v) => v >= 1000);
const nominalBoleh = new Set([
  ...prep.knowledge.filter((e) => e.auto_reply !== false && e.content_type !== 'price_reference').flatMap((e) => nominalDari(e.answer + ' ' + e.text)),
  ...nominalDari(JSON.stringify(ctx.orders || [])),
  ...nominalDari(ctx.message_text),
]);
// Total = harga satuan yang diizinkan x jumlah pcs/lusin yang disebut pelanggan juga boleh
const jumlah = (String(ctx.message_text).match(/(\d+)\s*(pcs|pc|buah|biji|lusin)/gi) || [])
  .map((m) => { const n = parseInt(m, 10); return /lusin/i.test(m) ? n * 12 : n; });
for (const harga of [...nominalBoleh]) for (const q of jumlah) nominalBoleh.add(harga * q);
const nominalAsing = action === 'AUTO_REPLY' ? nominalDari(reply).filter((v) => !nominalBoleh.has(v)) : [];
if (nominalAsing.length) {
  action = 'ESCALATE';
  parsed.needs_summary = 'Pelanggan menanyakan: ' + ctx.message_text;
  parsed.owner_question = 'Mohon konfirmasi harga/nominal untuk pertanyaan pelanggan ini (balasan otomatis ditahan karena nominalnya tidak ada di knowledge).';
}
// Saat eskalasi pertanyaan harga, sertakan referensi harga sebelumnya untuk owner
if (action !== 'AUTO_REPLY' && /harga|biaya|berapa|price|ongkir/i.test(ctx.message_text)) {
  // Hanya referensi yang topiknya sama dengan pertanyaan (kata >= 4 huruf yang sama)
  const kata = new Set(String(ctx.message_text).toLowerCase().match(/[a-z]{4,}/g) || []);
  const refs = prep.knowledge.filter((e) => e.content_type === 'price_reference')
    .filter((e) => (String(e.question + ' ' + e.answer).toLowerCase().match(/[a-z]{4,}/g) || []).some((w) => kata.has(w) && !['harga', 'berapa', 'untuk', 'kalau', 'pesan'].includes(w)))
